48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
70	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
71	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    /**
110	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
111	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
112	     */
113	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
114	        List<String> missing = new ArrayList<>();
115	        if (isBlank(ownerFieldsDto.getFirstName())) {
116	            missing.add("firstName");
117	        }
118	        if (isBlank(ownerFieldsDto.getLastName())) {
119	            missing.add("lastName");
120	        }
121	        if (isBlank(ownerFieldsDto.getAddress())) {
122	            missing.add("address");
123	        }
124	        if (isBlank(ownerFieldsDto.getCity())) {
125	            missing.add("city");
126	        }
127	        if (isBlank(ownerFieldsDto.getTelephone())) {
128	            missing.add("telephone");
129	        }
130	        if (!missing.isEmpty()) {
131	            throw new RequiredFieldsMissingException(missing);
132	        }
133	    }
134	
135	    private static boolean isBlank(String value) {
136	        return value == null || value.isBlank();
137	    }
138	
139	    /**
140	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
141	     * A leading {@code +} and its country code are kept as given; otherwise the country code
142	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
143	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
144	     * stored and returned.
145	     *
146	     * @param telephone the raw telephone as supplied by the caller
147	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
148	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
149	     */
150	    private static String normalizeTelephone(String telephone) {
151	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
152	        String e164;
153	        if (cleaned.startsWith("+")) {
154	            e164 = "+" + cleaned.substring(1);
155	        } else {
156	            String national = cleaned;
157	            if (national.startsWith("0")) {
158	                national = national.substring(1);
159	            }
160	            e164 = "+61" + national;
161	        }
162	        String digits = e164.substring(1);
163	        if (!digits.matches("\\d{8,15}")) {
164	            throw new InvalidTelephoneException(
165	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
166	        }
167	        return e164;
168	    }
169	
170	    /**
171	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
172	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
173	     *
174	     * @param email the raw email as supplied by the caller, may be {@code null}
175	     * @return the lower-cased email, or {@code null} when none was supplied
176	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
177	     */
178	    private static String normalizeEmail(String email) {
179	        if (email == null || email.isBlank()) {
180	            return null;
181	        }
182	        String trimmed = email.trim();
183	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
184	            throw new InvalidEmailException("Email must be a syntactically valid address");
185	        }
186	        return trimmed.toLowerCase(Locale.ROOT);
187	    }
188	
189	    /**
190	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
191	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
192	     * direct equality comparison of the E.164 values against the stored values is sufficient.
193	     *
194	     * @param normalizedTelephone the E.164 telephone of the owner being created
195	     * @throws DuplicateTelephoneException if another owner already uses this telephone
196	     */
197	    private void rejectDuplicateTelephone(String normalizedTelephone) {
198	        boolean inUse = this.clinicService.findAllOwners().stream()
199	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
200	        if (inUse) {
201	            throw new DuplicateTelephoneException(
202	                "Telephone is already used by another owner");
203	        }
204	    }
205	
206	    /**
207	     * Rejects a create that would place the owner in a household already occupied by another owner,
208	     * i.e. one whose last name and address match the supplied values. The two fields are compared
209	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
210	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
211	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
212	     * by setting {@code sharesHousehold} to {@code true}.
213	     *
214	     * @param lastName the last name of the owner being created
215	     * @param address the address of the owner being created
216	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
217	     */
218	    private void rejectDuplicateHousehold(String lastName, String address) {
219	        String normalizedLastName = normalizeForHousehold(lastName);
220	        String normalizedAddress = normalizeForHousehold(address);
221	        boolean inHousehold = this.clinicService.findAllOwners().stream()
222	            .anyMatch(existing ->
223	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
224	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
225	        if (inHousehold) {
226	            throw new DuplicateHouseholdException(
227	                "An owner with the same last name and address already exists");
228	        }
229	    }
230	
231	    /**
232	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
233	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
234	     *
235	     * @param value the raw value, may be {@code null}
236	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
237	     */
238	    private static String normalizeForHousehold(String value) {
239	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
240	    }
241	
242	    /**
243	     * Derives the stable household identifier for an owner from the normalized last name and address.
244	     * The value is a deterministic function of those two fields (compared case-insensitively with
245	     * collapsed whitespace, exactly as {@link #rejectDuplicateHousehold}), so every owner in the same
246	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
247	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
248	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
249	     * normalized fields.
250	     *
251	     * @param lastName the last name of the owner being created
252	     * @param address the address of the owner being created
253	     * @return the stable household identifier
254	     */
255	    private static String householdId(String lastName, String address) {
256	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
257	        try {
258	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
259	            StringBuilder sb = new StringBuilder(digest.length * 2);
260	            for (byte b : digest) {
261	                sb.append(String.format("%02x", b));
262	            }
263	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
264	        } catch (NoSuchAlgorithmException e) {
265	            throw new IllegalStateException("SHA-256 not available", e);
266	        }
267	    }
268	
269	    /**
270	     * Builds the customer code assigned to an owner on create, formatted {@code '<LAST3>-<NNNN>'}
271	     * where {@code LAST3} is the upper-cased first three letters of the owner's last name and
272	     * {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than the current
273	     * number of owners, e.g. {@code 'SMI-0007'}.
274	     *
275	     * @param lastName the last name of the owner being created
276	     * @return the formatted customer code
277	     */
278	    private String nextCustomerCode(String lastName) {
279	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
280	        int sequence = this.clinicService.findAllOwners().size() + 1;
281	        return String.format("%s-%04d", last3, sequence);
282	    }
